"""Sandbox reset for branched rollouts.

The trainer calls reset(traj, k) to get the sandbox a branch starts from: the rollout `traj`
as it was at step k. Returns the sandbox id; raises NotResettable when that state can't be restored.

Step k is the moment turn k+1 was sent (turns[k].sent_at, or ended_at when k == len(turns)).
"Exactly" is fingerprint() plus the tenant's staging services and shared volumes. Interpreter
internals that never appear there are ignored. A slightly wrong sandbox is not returned.
"""

import base64
import difflib
import fcntl
import json
import os
import shlex
import time
from concurrent.futures import ThreadPoolExecutor, wait

import sbx

class NotResettable(Exception):
    """This (rollout, step) can't be branched."""


_CACHE = "/tmp/branch-reset"
_VERSION = 2
# Boot is fast, but a little lead keeps the first turn from being late if create stalls.
# Keys are still sent at sent_at; the lead is only waited out.
_CLOCK_LEAD = 0.5


def reset(traj: dict, k: int) -> str:
    turns = traj.get("turns") or []
    if not isinstance(k, int) or isinstance(k, bool) or k < 0 or k > len(turns):
        raise NotResettable(f"step {k} is outside 0..{len(turns)}")
    if not traj.get("env") or not traj.get("tenant"):
        raise NotResettable("rollout is missing env or tenant")
    cal = _calibrate(traj, k)
    step = cal["steps"][str(k)]
    if not step["ok"]:
        raise NotResettable(step["reason"])
    with _lock("tenant-" + traj["tenant"]):
        return _reset_locked(traj, k, cal, step)


# -------------------------------------------------------------------------------------- calibration


def _calibrate(traj: dict, k: int) -> dict:
    key = _traj_key(traj)
    with _lock("cal-" + key):
        cal = _load_cal(traj)
        if cal is None:
            cal = _build_base(traj)
            _save_cal(traj, cal)
        if str(k) not in cal["steps"]:
            cal["steps"][str(k)] = _calibrate_step(traj, k, cal)
            _save_cal(traj, cal)
        return cal


def _build_base(traj: dict) -> dict:
    info = sbx.env_info(traj["env"])
    mounts = [m["path"] for m in info.get("mounts") or []]
    declared = list(info.get("services") or [])
    initial_volumes = {}
    services = []
    probe = sbx.create(traj["env"])
    try:
        _wait_shell(probe)
        for path in mounts:
            initial_volumes[path] = _export_tree(probe, path)
        for svc in declared:
            host = svc["host"]
            journal, ok = _read_journal(probe, host)
            rewindable = False
            initial_seq = 0
            if ok:
                initial_seq = journal[-1]["seq"] if journal else 0
                try:
                    _rewind(probe, host, initial_seq)
                    rewindable = True
                except NotResettable:
                    rewindable = False
            services.append({
                "name": svc["name"],
                "host": host,
                "port": int(svc.get("port") or 80),
                "rewindable": rewindable,
                "initial_seq": initial_seq,
            })
    finally:
        probe.terminate()
    return {
        "version": _VERSION,
        "created_at": traj["created_at"],
        "env": traj["env"],
        "tenant": traj["tenant"],
        "mounts": mounts,
        "services": services,
        "initial_volumes": initial_volumes,
        "full_mutations": None,
        "steps": {},
    }


def _calibrate_step(traj: dict, k: int, cal: dict) -> dict:
    """Two clock-aligned scratch replays to step k. Disagreeing state is not resettable
    unless the only difference is file bytes the rollout observation pins down."""
    need_full = cal["full_mutations"] is None and any(not s["rewindable"] for s in cal["services"])
    futs = []
    with ThreadPoolExecutor(max_workers=3) as pool:
        futs.append(pool.submit(_replay_open, traj, k, cal))
        futs.append(pool.submit(_replay_open, traj, k, cal))
        full_fut = pool.submit(_full_mutations, traj, cal) if need_full else None
        done, _ = wait(futs)
        if full_fut is not None:
            wait([full_fut])
        opened = []
        try:
            for fut in futs:
                opened.append(fut.result())
            if full_fut is not None:
                cal["full_mutations"] = full_fut.result()
            recs = [rec for _, rec in opened]
            sbs = [sb for sb, _ in opened]
            return _judge_step(traj, k, recs[0], recs[1], sbs[0], sbs[1], cal)
        finally:
            for item in opened:
                try:
                    item[0].terminate()
                except Exception:
                    pass


def _replay_open(traj, k, cal):
    """Replay turns[:k] on a scratch tenant and leave the sandbox at the step boundary."""
    first = traj["turns"][0]["sent_at"] if traj.get("turns") else None
    sb = _create_aligned(traj["env"], traj["created_at"], first_sent_at=first)
    try:
        screens = []
        _replay_prefix(sb, traj, k, screens)
        rec = _snapshot_step(sb, cal)
        rec["screens"] = screens
        return sb, rec
    except Exception:
        sb.terminate()
        raise


def _full_mutations(traj, cal):
    first = traj["turns"][0]["sent_at"] if traj.get("turns") else None
    sb = _create_aligned(traj["env"], traj["created_at"], first_sent_at=first)
    try:
        _replay_prefix(sb, traj, len(traj.get("turns") or []), [])
        return _mutations(sb.egress())
    finally:
        sb.terminate()


def _replay_prefix(sb, traj, k, screens) -> None:
    _wait_shell(sb)
    turns = traj.get("turns") or []
    if k == 0:
        boundary = turns[0]["sent_at"] if turns else traj.get("ended_at", traj["created_at"])
        _wait_clock(sb, boundary)
        return
    for i in range(k):
        _play_turn(sb, turns[i])
        screens.append(sb.capture())
    boundary = turns[k]["sent_at"] if k < len(turns) else traj["ended_at"]
    _wait_clock(sb, boundary)


def _snapshot_step(sb, cal) -> dict:
    fp = sb.fingerprint(detail=True)
    vols = {path: _tree_sig(sb, path) for path in cal["mounts"]}
    journals = {}
    for svc in cal["services"]:
        if not svc["rewindable"]:
            continue
        journal, ok = _read_journal(sb, svc["host"])
        journals[svc["name"]] = journal if ok else None
    return {
        "fp": fp["fingerprint"],
        "detail": fp["detail"],
        "vols": vols,
        "journals": journals,
        "egress": sb.egress(),
    }


def _judge_step(traj, k, a, b, sb_a, sb_b, cal) -> dict:
    patches = []
    reason = _divergence_reason(a, b)
    if reason:
        patches = _derive_patches(traj, k, a, b, sb_a, sb_b)
        if not patches:
            return _bad(reason)

    sink_hosts = []
    for svc in cal["services"]:
        if svc["rewindable"]:
            ja = (a["journals"] or {}).get(svc["name"])
            jb = (b["journals"] or {}).get(svc["name"])
            if ja is None or ja != jb:
                return _bad(f"service {svc['name']} journal is not replay-stable")
            continue
        prefix = _mutations(a["egress"], svc["name"])
        if prefix != _mutations(b["egress"], svc["name"]):
            return _bad(f"service {svc['name']} requests are not replay-stable")
        full = [m for m in (cal.get("full_mutations") or []) if m["service"] == svc["name"]]
        if prefix != full:
            return _bad(f"service {svc['name']} cannot be restored to this step")
        if full:
            sink_hosts.append(svc["host"])

    return {
        "ok": True,
        "reason": "",
        "patches": patches,
        "sink_hosts": sink_hosts,
        "fp": a["fp"],
        "detail": a["detail"],
        "vols": a["vols"],
        "journals": a["journals"],
    }


def _bad(reason: str) -> dict:
    return {"ok": False, "reason": reason, "patches": [], "sink_hosts": []}


def _divergence_reason(a, b) -> str:
    bits = []
    for key in ("files", "processes", "ports", "shell", "repl", "services"):
        if a["fp"].get(key) != b["fp"].get(key):
            bits.append(key)
    for path, sig in a["vols"].items():
        if sig != b["vols"].get(path):
            bits.append("volume " + path)
    for name, journal in a["journals"].items():
        if journal != b["journals"].get(name):
            bits.append("journal " + name)
    if not bits:
        return ""
    return "two replays disagree in " + ", ".join(bits)


def _other_differ(a, b) -> bool:
    for key in ("processes", "ports", "shell", "repl", "services"):
        if a["fp"].get(key) != b["fp"].get(key):
            return True
    for path, sig in a["vols"].items():
        if sig != b["vols"].get(path):
            return True
    for name, journal in a["journals"].items():
        if journal != b["journals"].get(name):
            return True
    return False


def _parse_file_line(line: str):
    parts = line.split()
    if len(parts) < 4:
        return None
    kind = parts[0]
    if len(parts[-1]) == 64 and all(c in "0123456789abcdef" for c in parts[-1]):
        digest = parts[-1]
        owner = parts[-2]
        mode = parts[-3]
        path = " ".join(parts[1:-3])
        return kind, path, mode, owner, digest
    owner = parts[-1]
    mode = parts[-2]
    path = " ".join(parts[1:-2])
    return kind, path, mode, owner, None


def _content_only_paths(a, b):
    """Paths whose regular-file bytes differ and nothing else about the entry does.

    Returns None when the file trees differ in a way bytes cannot repair (renames,
    mode, owner, sqlite dumps, added or removed paths).
    """
    da = a["detail"].get("files") or []
    db = b["detail"].get("files") or []
    ma = {}
    mb = {}
    for ln in da:
        parsed = _parse_file_line(ln)
        if parsed:
            ma[parsed[1]] = parsed
    for ln in db:
        parsed = _parse_file_line(ln)
        if parsed:
            mb[parsed[1]] = parsed
    if set(ma) != set(mb):
        return None
    paths = []
    for path, pa in ma.items():
        pb = mb[path]
        if pa == pb:
            continue
        kind_a, _, mode_a, owner_a, digest_a = pa
        kind_b, _, mode_b, owner_b, digest_b = pb
        if kind_a != "f" or kind_b != "f":
            return None
        if mode_a != mode_b or owner_a != owner_b or digest_a == digest_b:
            return None
        paths.append(path)
    return paths


def _derive_patches(traj, k, a, b, sb_a, sb_b):
    if _other_differ(a, b):
        return None
    paths = _content_only_paths(a, b)
    if not paths:
        return None
    turns = (traj.get("turns") or [])[:k]
    reps_a = _screen_replacements(a["screens"], turns)
    reps_b = _screen_replacements(b["screens"], turns)
    patches = []
    for path in paths:
        data_a = _read_bytes(sb_a, path)
        data_b = _read_bytes(sb_b, path)
        if data_a is None or data_b is None or data_a == data_b:
            return None
        pinned = _pin_bytes(data_a, data_b, reps_a, reps_b)
        if pinned is None:
            return None
        patches.append({"path": path, "b64": base64.b64encode(pinned).decode()})
    return patches


def _screen_replacements(screens, turns):
    reps = []
    for screen, turn in zip(screens, turns):
        got = [ln.rstrip() for ln in screen.splitlines()]
        want = [ln.rstrip() for ln in (turn.get("observation") or "").splitlines()]
        matcher = difflib.SequenceMatcher(a=got, b=want, autojunk=False)
        for tag, i1, i2, j1, j2 in matcher.get_opcodes():
            if tag != "replace" or (i2 - i1) != (j2 - j1):
                continue
            for old, new in zip(got[i1:i2], want[j1:j2]):
                if old != new and old and new:
                    reps.append((old, new))
    return reps


def _pin_bytes(data_a, data_b, reps_a, reps_b):
    whole_a = _pin_whole(data_a, reps_a)
    whole_b = _pin_whole(data_b, reps_b)
    if whole_a is not None and whole_a == whole_b and whole_a != data_a:
        return whole_a
    try:
        text_a = data_a.decode("utf-8")
        text_b = data_b.decode("utf-8")
    except UnicodeDecodeError:
        return None
    new_a = _apply_line_reps(text_a, reps_a)
    new_b = _apply_line_reps(text_b, reps_b)
    if new_a is None or new_a != new_b:
        return None
    raw = new_a.encode("utf-8")
    if raw == data_a or raw == data_b:
        return None
    return raw


def _pin_whole(data, reps):
    newline = data.endswith(b"\n")
    body = data[:-1] if newline else data
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        return None
    for old, new in reps:
        if text == old:
            out = new.encode("utf-8")
            return out + b"\n" if newline else out
    return None


def _apply_line_reps(text, reps):
    lines = text.splitlines()
    used = [False] * len(reps)
    changed = False
    out = []
    for line in lines:
        repl = None
        for i, (old, new) in enumerate(reps):
            if not used[i] and line == old:
                repl = new
                used[i] = True
                break
        if repl is None:
            out.append(line)
        else:
            out.append(repl)
            changed = True
    if not changed:
        return None
    result = "\n".join(out)
    if text.endswith("\n"):
        result += "\n"
    return result


def _mutations(egress, service=None):
    out = []
    for rec in egress or []:
        if service is not None and rec.get("service") != service:
            continue
        req = rec.get("request") or ""
        method = req.split(" ", 1)[0].upper()
        if method in ("", "GET", "HEAD"):
            continue
        if "/_admin/" in req:
            continue
        out.append({"service": rec.get("service"), "method": method, "request": req})
    return out


# -------------------------------------------------------------------------------------- reset


def _reset_locked(traj, k, cal, step) -> str:
    backup = _backup_tenant(traj, cal)
    helper = None
    branch = None
    try:
        if cal["mounts"] or any(s["rewindable"] for s in cal["services"]):
            helper = sbx.create(traj["env"], tenant=traj["tenant"])
            _wait_shell(helper)
            for path, blob in cal["initial_volumes"].items():
                _import_tree(helper, path, blob)
            for svc in cal["services"]:
                if svc["rewindable"]:
                    _rewind(helper, svc["host"], svc["initial_seq"])
            helper.terminate()
            helper = None

        first = traj["turns"][0]["sent_at"] if traj.get("turns") else None
        branch = _create_aligned(
            traj["env"], traj["created_at"], tenant=traj["tenant"], first_sent_at=first,
        )
        if branch.tenant != traj["tenant"]:
            raise NotResettable("sandbox was not created on the rollout tenant")
        saved_hosts = None
        if step["sink_hosts"]:
            saved_hosts = _blackhole_hosts(branch, step["sink_hosts"])
        _replay_prefix(branch, traj, k, [])
        if step["patches"]:
            _apply_patches(branch, step["patches"])
        if saved_hosts is not None:
            _write_file(branch, "/etc/hosts", saved_hosts)
        if step["sink_hosts"] and _mutations(branch.egress()):
            leaked = [m for m in _mutations(branch.egress()) if m["service"]]
            sunk = set(step["sink_hosts"])
            names = {s["name"] for s in cal["services"] if s["host"] in sunk}
            if any(m["service"] in names for m in leaked):
                raise NotResettable("staging service was mutated again during replay")
        if not _matches_reference(branch, step):
            raise NotResettable("restored sandbox fingerprint does not match the rollout")
        if not _tenant_matches(branch, step, cal):
            raise NotResettable("restored tenant does not match the rollout")
        sid = branch.id
        branch = None
        return sid
    except NotResettable:
        _restore_backup(traj, cal, backup)
        raise
    except Exception as exc:
        _restore_backup(traj, cal, backup)
        raise NotResettable(f"reset failed: {type(exc).__name__}: {exc}") from exc
    finally:
        for sb in (helper, branch):
            if sb is None:
                continue
            try:
                sb.terminate()
            except Exception:
                pass


def _matches_reference(sb, step) -> bool:
    got = sb.fingerprint(detail=True)
    fp = step["fp"]
    for key in ("processes", "ports", "shell", "repl", "services"):
        if got["fingerprint"].get(key) != fp.get(key):
            return False
    patched = {p["path"] for p in step.get("patches") or []}
    if not patched:
        return got["fingerprint"].get("files") == fp.get("files")
    return _files_equivalent(got["detail"].get("files") or [], step["detail"].get("files") or [], patched)


def _files_equivalent(got_lines, ref_lines, patched) -> bool:
    def index(lines):
        out = {}
        for ln in lines:
            parsed = _parse_file_line(ln)
            if parsed:
                out[parsed[1]] = parsed
        return out

    got = index(got_lines)
    ref = index(ref_lines)
    if set(got) != set(ref):
        return False
    for path, gp in got.items():
        rp = ref[path]
        if path in patched:
            if gp[0] != rp[0] or gp[2] != rp[2] or gp[3] != rp[3]:
                return False
            continue
        if gp != rp:
            return False
    return True


def _tenant_matches(sb, step, cal) -> bool:
    for path, sig in (step.get("vols") or {}).items():
        if _tree_sig(sb, path) != sig:
            return False
    for svc in cal["services"]:
        if not svc["rewindable"]:
            continue
        journal, ok = _read_journal(sb, svc["host"])
        if not ok or journal != (step.get("journals") or {}).get(svc["name"]):
            return False
    return True


def _apply_patches(sb, patches) -> None:
    script = r"""
import base64, json, os, sys
specs = json.loads(sys.stdin.read())
for spec in specs:
    path = spec["path"]
    data = base64.b64decode(spec["b64"])
    fd = os.open(path, os.O_WRONLY | os.O_TRUNC)
    try:
        os.write(fd, data)
    finally:
        os.close(fd)
print("ok")
"""
    payload = json.dumps(patches)
    r = sb.exec(["python3", "-c", script], stdin=payload)
    if r["rc"] != 0 or "ok" not in r["stdout"]:
        raise NotResettable(f"could not apply observed file bytes: {r['stderr'][:200]}")


def _blackhole_hosts(sb, hosts) -> str:
    """Point staging hostnames at an address with no listener so replay cannot double-apply.

    Used only when every mutation of a non-rewindable service is already in the prefix,
    so the live tenant is already at this step. Connection refusals must not change
    fingerprint-visible state; the caller checks that and refuses if they do.
    """
    original = sb.exec(["cat", "/etc/hosts"])["stdout"]
    if not original.endswith("\n"):
        original += "\n"
    blocked = set(hosts)
    lines = []
    for line in original.splitlines():
        parts = line.split()
        if len(parts) >= 2 and any(h in parts[1:] for h in blocked):
            continue
        lines.append(line)
    for host in hosts:
        lines.append("127.255.255.254 " + host)
    _write_file(sb, "/etc/hosts", "\n".join(lines) + "\n")
    return original


# -------------------------------------------------------------------------------------- tenant io


def _backup_tenant(traj, cal) -> dict:
    root = os.path.join(_CACHE, "backup", _safe(traj["tenant"]))
    os.makedirs(root, exist_ok=True)
    marker = os.path.join(root, "done")
    if os.path.exists(marker):
        return {"root": root}
    if not cal["mounts"] and not any(s["rewindable"] for s in cal["services"]):
        _write_text(marker, "empty\n")
        return {"root": root}
    sb = sbx.create(traj["env"], tenant=traj["tenant"])
    try:
        _wait_shell(sb)
        for path in cal["initial_volumes"]:
            _write_text(os.path.join(root, _safe(path) + ".b64"), _export_tree(sb, path))
        for svc in cal["services"]:
            if not svc["rewindable"]:
                continue
            journal, ok = _read_journal(sb, svc["host"])
            if not ok:
                raise NotResettable(f"could not read journal for {svc['name']} before rewind")
            _write_json(os.path.join(root, "journal-" + svc["name"] + ".json"), journal)
    finally:
        sb.terminate()
    _write_text(marker, "ok\n")
    return {"root": root}


def _restore_backup(traj, cal, backup) -> None:
    if not backup:
        return
    root = backup["root"]
    if not cal["mounts"] and not any(s["rewindable"] for s in cal["services"]):
        return
    sb = None
    try:
        sb = sbx.create(traj["env"], tenant=traj["tenant"])
        _wait_shell(sb)
        for path in cal["initial_volumes"]:
            blob = _read_text(os.path.join(root, _safe(path) + ".b64"))
            if blob:
                _import_tree(sb, path, blob.strip())
        for svc in cal["services"]:
            if not svc["rewindable"]:
                continue
            journal = _read_json(os.path.join(root, "journal-" + svc["name"] + ".json"))
            if journal is None:
                continue
            _rewind(sb, svc["host"], 0)
            for entry in journal:
                _replay_journal_entry(sb, svc["host"], entry)
    finally:
        if sb is not None:
            try:
                sb.terminate()
            except Exception:
                pass


def _export_tree(sb, path) -> str:
    r = sb.exec(f"tar -C {shlex.quote(path)} -cf - . | base64 -w0")
    if r["rc"] != 0 or not r["stdout"].strip():
        raise NotResettable(f"could not read volume {path}: {r['stderr'][:200]}")
    return r["stdout"].strip()


def _import_tree(sb, path, blob: str) -> None:
    quoted = shlex.quote(path)
    clear = sb.exec(f"find {quoted} -mindepth 1 -delete")
    if clear["rc"] != 0:
        raise NotResettable(f"could not clear volume {path}: {clear['stderr'][:200]}")
    r = sb.exec(f"base64 -d | tar -C {quoted} -xf -", stdin=blob)
    if r["rc"] != 0:
        raise NotResettable(f"could not restore volume {path}: {r['stderr'][:200]}")


def _tree_sig(sb, path) -> str:
    quoted = shlex.quote(path)
    r = sb.exec(
        f"cd {quoted} && find . -printf '%y %m %p\\n' | sort && echo '---' && "
        f"find . -type f -print0 | sort -z | xargs -0 -r sha256sum"
    )
    if r["rc"] != 0:
        return "ERR " + (r["stderr"] or "")[:80]
    return r["stdout"]


def _read_bytes(sb, path):
    r = sb.exec(
        ["python3", "-c",
         "import sys,base64; sys.stdout.write(base64.b64encode(open(sys.argv[1],'rb').read()).decode())",
         path]
    )
    if r["rc"] != 0:
        return None
    try:
        return base64.b64decode(r["stdout"].strip())
    except ValueError:
        return None


def _read_journal(sb, host):
    r = sb.exec(["curl", "-sS", "-m", "8", "-w", "\n%{http_code}", f"http://{host}/_admin/journal"])
    if r["rc"] != 0:
        return None, False
    head, _, code = r["stdout"].rpartition("\n")
    if code.strip() != "200":
        return None, False
    try:
        data = json.loads(head)
    except ValueError:
        return None, False
    if not isinstance(data, list):
        return None, False
    return data, True


def _rewind(sb, host, seq: int) -> None:
    payload = json.dumps({"seq": seq})
    r = sb.exec([
        "curl", "-sS", "-m", "15", "-X", "POST", "-H", "Content-Type: application/json",
        "-d", payload, "-w", "\n%{http_code}", f"http://{host}/_admin/rewind",
    ])
    if r["rc"] != 0:
        raise NotResettable(f"rewind failed: {r['stderr'][:200]}")
    head, _, code = r["stdout"].rpartition("\n")
    if not code.strip().startswith("2"):
        raise NotResettable(f"rewind rejected: {head[:200]}")


def _replay_journal_entry(sb, host, entry) -> None:
    method = entry.get("method") or "POST"
    path = entry.get("path") or "/"
    if not path.startswith("/"):
        path = "/" + path
    body = entry.get("body")
    cmd = [
        "curl", "-sS", "-m", "15", "-X", method, "-o", "/dev/null", "-w", "%{http_code}",
        f"http://{host}{path}",
    ]
    if body is not None:
        payload = body if isinstance(body, str) else json.dumps(body)
        cmd[1:1] = ["-H", "Content-Type: application/json", "-d", payload]
    r = sb.exec(cmd)
    if r["rc"] != 0 or not (r["stdout"] or "").strip().startswith("2"):
        raise NotResettable(f"could not replay journal entry {method} {path}: {(r['stdout'] or '')[:120]}")


def _write_file(sb, path, text: str) -> None:
    r = sb.exec(["tee", path], stdin=text)
    if r["rc"] != 0:
        raise NotResettable(f"could not write {path}")


# -------------------------------------------------------------------------------------- replay timing


def _create_aligned(env, created_at, tenant=None, first_sent_at=None):
    lead = _CLOCK_LEAD
    last = None
    for _ in range(3):
        offset = created_at - time.time() - lead
        if offset == 0:
            offset = -0.001
        kwargs = {"clock_offset": offset}
        if tenant:
            kwargs["tenant"] = tenant
        sb = sbx.create(env, **kwargs)
        try:
            _wait_shell(sb)
        except Exception:
            try:
                sb.terminate()
            except Exception:
                pass
            raise
        if first_sent_at is None or sb.clock() < first_sent_at - 0.05:
            return sb
        last = sb
        try:
            sb.terminate()
        except Exception:
            pass
        last = None
        lead += 2.0
    if last is not None:
        try:
            last.terminate()
        except Exception:
            pass
    raise NotResettable("sandbox boot overran the first turn")


def _wait_shell(sb, timeout=20) -> None:
    deadline = time.time() + timeout
    while time.time() < deadline:
        r = sb.exec("test -f /run/sbx/state/shell && echo up", timeout=10)
        if r["stdout"].strip() == "up":
            return
        time.sleep(0.05)
    raise NotResettable("sandbox shell did not come up")


def _wait_clock(sb, target, timeout=180) -> None:
    deadline = time.time() + timeout
    while time.time() < deadline:
        now = sb.clock()
        if now >= target - 0.003:
            return
        remain = target - now
        time.sleep(min(max(remain * 0.4, 0.001), 0.05))
    raise NotResettable("sandbox clock did not reach the step boundary")


def _play_turn(sb, turn) -> None:
    _wait_clock(sb, turn["sent_at"])
    sb.keys(turn["keys"])
    _wait_clock(sb, turn["captured_at"] + 0.02)


# -------------------------------------------------------------------------------------- cache / locks


def _traj_key(traj) -> str:
    return _safe(traj.get("traj_id") or f"{traj.get('env')}-{traj.get('tenant')}")


def _cal_path(traj) -> str:
    return os.path.join(_CACHE, "cal", _traj_key(traj) + ".json")


def _vol_path(traj, mount) -> str:
    return os.path.join(_CACHE, "vol", _traj_key(traj), _safe(mount) + ".b64")


def _load_cal(traj):
    data = _read_json(_cal_path(traj))
    if not data or data.get("version") != _VERSION or data.get("created_at") != traj["created_at"]:
        return None
    if data.get("env") != traj["env"] or data.get("tenant") != traj["tenant"]:
        return None
    volumes = {}
    for path in data.get("mounts") or []:
        blob = _read_text(_vol_path(traj, path))
        if not blob:
            return None
        volumes[path] = blob.strip()
    data["initial_volumes"] = volumes
    data.setdefault("steps", {})
    return data


def _save_cal(traj, cal) -> None:
    for path, blob in (cal.get("initial_volumes") or {}).items():
        _write_text(_vol_path(traj, path), blob)
    data = {k: v for k, v in cal.items() if k != "initial_volumes"}
    _write_json(_cal_path(traj), data)


class _lock:
    def __init__(self, name):
        os.makedirs(os.path.join(_CACHE, "locks"), exist_ok=True)
        self.path = os.path.join(_CACHE, "locks", _safe(name))
        self.fh = None

    def __enter__(self):
        self.fh = open(self.path, "a+")
        fcntl.flock(self.fh, fcntl.LOCK_EX)
        return self

    def __exit__(self, *args):
        try:
            fcntl.flock(self.fh, fcntl.LOCK_UN)
        finally:
            self.fh.close()


def _safe(text: str) -> str:
    return "".join(ch if ch.isalnum() or ch in "._-" else "_" for ch in str(text))[:180]


def _read_json(path):
    try:
        with open(path) as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


def _write_json(path, obj) -> None:
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(obj, f)
    os.replace(tmp, path)


def _read_text(path):
    try:
        with open(path) as f:
            return f.read()
    except OSError:
        return None


def _write_text(path, text) -> None:
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        f.write(text)
    os.replace(tmp, path)

